    <section class="career-dash-metrics" aria-label="Career snapshot"><article class="career-metric-card career-profile-metric"><span class="career-metric-icon">◌</span><div><small>Profile strength</small><strong id="overviewProfileStrength">72%</strong><span class="career-metric-caption">A good start</span></div><button class="career-metric-link" data-custom-view="profile" aria-label="Improve your profile">↗</button><div class="career-meter"><i style="width:72%"></i></div></article><article class="career-metric-card"><span class="career-metric-icon coral">♡</span><div><small>Saved roles</small><strong id="overviewSavedCount">0</strong><span class="career-metric-caption">Keep your shortlist close</span></div><button class="career-metric-link" data-existing-jobs aria-label="View saved roles">↗</button></article><article class="career-metric-card"><span class="career-metric-icon mint">↗</span><div><small>Applications</small><strong id="overviewApplicationCount">0</strong><span class="career-metric-caption">Your journey, in one place</span></div><button class="career-metric-link" data-existing-tracker aria-label="View applications">↗</button></article><article class="career-metric-card career-resume-metric"><span class="career-metric-icon violet">▤</span><div><small>Resume workspace</small><strong>Ready when you are</strong><span class="career-metric-caption">Build and review a tailored draft</span></div><button class="career-metric-link" data-enter-studio aria-label="Open resume builder">↗</button></article></section>
